void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;

    // Time varying pixel color
    vec3 col = vec3(0.0, 0.0, 0.0);
    col += vec3(0,1,1) * min(0.2 / abs((distance(uv, vec2(0.5, 0.5)) - 0.25) * 30.), 1.0);
    if (uv.x > 0.5 + sin(iTime) / 4. && uv.x < 1.0) {
        col += vec3(1,1,1) * min(0.005 / abs(uv.y - 0.5 - cos(iTime) / 4.) / 5.0, 1.0);
    }
    else {
        col += vec3(1,1,1) * min(0.005 / distance(uv, vec2(0.5 + sin(iTime), 0.5 + cos(iTime))));
    }
    col += vec3(1,1,1) * min(0.02 / distance(uv, vec2(0.5 + sin(iTime) / 4., 0.5 + cos(iTime) / 4.)), 1.0);
    col += vec3(1,1,1) * min(0.02 / distance(uv, vec2(1.0, 0.5 + cos(iTime) / 4.)), 1.0);
    col += vec3(1,1,1) * min(0.003 / abs(uv.x - 1.0), 1.0);
    if (uv.x > 1.0) {
        col += vec3(1,0.5,0.5) * min(0.01 / abs(uv.y - (0.5 + cos(-iTime + (uv.x - 1.0) * 16.) / 4.0)), 1.0);
    }
    // Output to screen
    fragColor = vec4(col,1.0);
}
